"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[311],{6261:e=>{e.exports=JSON.parse('{"functions":[{"name":"ensureNetStarted","desc":"Ensures the networking layer has been started exactly once.\\nStruktura defers starting `Net` until it actually needs it (e.g. during [Struktura.Start] or\\nwhen a client calls [Struktura.GetService]).","params":[],"returns":[],"function_type":"static","private":true,"source":{"line":237,"path":"src/init.luau"}},{"name":"isPromiseLike","desc":"Returns true when `value` looks like a Promise implementation compatible with Struktura.\\nStruktura only relies on `andThen`, `catch`, and `await`.","params":[{"name":"value","desc":"","lua_type":"any"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","private":true,"source":{"line":251,"path":"src/init.luau"}},{"name":"toPromise","desc":"Normalizes an `Init`/`Start` return value into a Promise-like object.\\n- `nil` becomes a resolved promise\\n- a Promise-like value is returned as-is\\n- anything else becomes `Promise.resolve(value)`","params":[{"name":"value","desc":"","lua_type":"any"}],"returns":[{"desc":"","lua_type":"PromiseLike\\n"}],"function_type":"static","private":true,"source":{"line":266,"path":"src/init.luau"}},{"name":"feed","desc":"Requires a ModuleScript and registers it as a service or controller.\\nIf the module table has `Type == \\"Controller\\"`, it is stored in the controller set; otherwise it is\\ntreated as a server service module.","params":[{"name":"moduleScript","desc":"","lua_type":"ModuleScript"}],"returns":[{"desc":"True if the module was processed, false if feeding was rejected (already started).","lua_type":"boolean"}],"function_type":"static","errors":[{"lua_type":"string","desc":"Throws if requiring the module errors."}],"private":true,"source":{"line":286,"path":"src/init.luau"}},{"name":"bindLifecycle","desc":"Binds a lifecycle `signal` to call `On<name>` on every loaded module in the current realm.\\nFor example, binding `\\"PlayerAdded\\"` will invoke `module.OnPlayerAdded(module, player)` for every module\\nthat defines it.","params":[{"name":"name","desc":"","lua_type":"string"},{"name":"signal","desc":"","lua_type":"EventSignal?"}],"returns":[],"function_type":"static","private":true,"source":{"line":325,"path":"src/init.luau"}},{"name":"createServerSignal","desc":"Creates a server signal object that routes through `Net:Fire` using `netName` + `eventName`.","params":[{"name":"netName","desc":"","lua_type":"string"},{"name":"eventName","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"ServerSignal<...any>\\n"}],"function_type":"static","realm":["Server"],"private":true,"source":{"line":357,"path":"src/init.luau"}},{"name":"setupClientSurface","desc":"Scans service `Client` tables and registers:\\n- Signal markers (from [Struktura.CreateSignal]) as server signal objects\\n- Client RPC handlers for functions declared in `Client`\\n- The `__struktura_meta` handler used by [Struktura.GetService] on the client","params":[],"returns":[],"function_type":"static","realm":["Server"],"private":true,"source":{"line":388,"path":"src/init.luau"}},{"name":"Configure","desc":"Configures Struktura runtime options.\\nThis is usually called once during boot, before [Struktura.Start].\\n`ServicePromises` controls how client-side service method calls behave:\\n- `true` (default): methods return a Promise-like object from `Net:Request(...)`\\n- `false`: methods synchronously `:await()` the request and return the result (this yields)","params":[{"name":"options","desc":"Configuration overrides.","lua_type":"Settings?"}],"returns":[],"function_type":"static","source":{"line":431,"path":"src/init.luau"}},{"name":"CreateLifecycle","desc":"Creates and (optionally) binds a custom lifecycle event.\\nOnce created, any module can listen by implementing a method named `On<name>`. For example, if you create\\na lifecycle named `\\"RoundStarted\\"`, modules may implement `OnRoundStarted(...)`.\\nIf Struktura has already started (or is in the process of starting), the lifecycle is bound immediately.\\nOtherwise, it will be bound during [Struktura.Start].","params":[{"name":"name","desc":"Lifecycle name (without the `On` prefix).","lua_type":"string"},{"name":"signal","desc":"Any object with `:Connect(callback)` that returns a disconnectable connection.","lua_type":"EventSignal"}],"returns":[{"desc":"Resolves when the lifecycle is registered; rejects if it already exists.","lua_type":"PromiseLike"}],"function_type":"static","source":{"line":454,"path":"src/init.luau"}},{"name":"CreateSignal","desc":"Creates a **signal marker** for use inside a service\'s `Client` table (server only).\\nThis does **not** create a real Signal object. Instead, it returns an opaque marker used by Struktura\\nduring [Struktura.Start] to convert the field into a server signal wrapper (see [ServerSignal]).\\nExample:\\n```lua\\nlocal MyService = { Name = \\"MyService\\" }\\nMyService.Client = {\\n    Pinged = Struktura.CreateSignal(),\\n}\\nfunction MyService:Start()\\n    self.Client.Pinged:FireAll(\\"hello\\")\\nend\\n```","params":[],"returns":[{"desc":"The internal marker object.","lua_type":"any"}],"function_type":"static","realm":["Server"],"source":{"line":490,"path":"src/init.luau"}},{"name":"OnStart","desc":"Returns a promise that resolves once Struktura has finished starting.\\nThis is useful when a controller wants to wait until all `Init` functions have run and services have been\\nsurfaced on the server.","params":[],"returns":[{"desc":"","lua_type":"PromiseLike"}],"function_type":"static","yields":true,"source":{"line":507,"path":"src/init.luau"}},{"name":"Initialize","desc":"Loads (requires) modules from a container folder and registers them with Struktura.\\n- If `deep` is truthy, Struktura scans all descendants; otherwise it only scans direct children.\\n- Any module that returns a table is registered.\\n- If that table has `Type == \\"Controller\\"`, it\'s treated as a controller (client). Otherwise it\'s a service (server).\\nYou must call this before [Struktura.Start] if you want modules to participate in lifecycle events.","params":[{"name":"container","desc":"Folder containing modules.","lua_type":"Folder"},{"name":"deep","desc":"Whether to include descendants.","lua_type":"boolean?"}],"returns":[{"desc":"Resolves with a timing string when initialization completes.","lua_type":"PromiseLike"}],"function_type":"static","source":{"line":533,"path":"src/init.luau"}},{"name":"GetController","desc":"Returns a previously-initialized controller by name (client only).\\nControllers are registered during [Struktura.Initialize]. Names come from the returned table\'s `Name` field\\nor fall back to the ModuleScript name.","params":[{"name":"name","desc":"Controller name.","lua_type":"string"}],"returns":[{"desc":"The controller table if found, otherwise `nil`.","lua_type":"T?"}],"function_type":"static","realm":["Client"],"source":{"line":563,"path":"src/init.luau"}},{"name":"GetService","desc":"Returns a service by name.\\nBehavior differs by realm:\\n- **Server:** returns the raw service module table that was loaded during [Struktura.Initialize].\\n- **Client:** builds and caches a proxy based on server-provided metadata.\\nThe client proxy exposes:\\n- Signal fields as objects with `:Connect(callback)`\\n- Method calls via `Service:MethodName(...)` (implemented through `__index`)\\nBy default, calling a method returns a Promise-like value. You can change this with [Struktura.Configure].","params":[{"name":"name","desc":"Service name.","lua_type":"string"}],"returns":[{"desc":"Service table (server) or proxy (client).","lua_type":"T"}],"function_type":"static","errors":[{"lua_type":"string","desc":"Throws on client if service metadata cannot be fetched."}],"realm":["Client","Server"],"yields":true,"source":{"line":610,"path":"src/init.luau"}},{"name":"Start","desc":"Starts Struktura: binds lifecycle events, starts networking, and runs module `Init`/`Start` hooks.\\nStart order:\\n1. Ensures `Net` is started\\n2. Binds lifecycle signals (built-in and custom)\\n3. Runs `Init` on every loaded module (services on server, controllers on client)\\n4. On server, surfaces service `Client` tables (RPC + signals)\\n5. Marks Struktura as started and then runs `Start` for each module asynchronously\\nOn the client, Struktura will wait for the server to set the `ServerReady` attribute before continuing.","params":[],"returns":[{"desc":"Resolves with a timing string when initialization hooks complete.","lua_type":"PromiseLike"}],"function_type":"static","realm":["Client","Server"],"yields":true,"source":{"line":685,"path":"src/init.luau"}}],"properties":[{"name":"Net","desc":"Low-level networking implementation used by Struktura.\\nMost projects should not need to touch this directly; prefer [Struktura.GetService],\\nservice `Client` methods, and `Client` signals created via [Struktura.CreateSignal].","lua_type":"any","source":{"line":194,"path":"src/init.luau"}}],"types":[{"name":"PlayerName","desc":"Convenience alias for `Player.Name` when using the framework APIs.","lua_type":"string","source":{"line":62,"path":"src/init.luau"}},{"name":"Target","desc":"The set of supported target formats for server \u2192 client signals.\\n- `Player`: fire to a specific player\\n- `PlayerName` / `{ PlayerName }`: fire to one or more players by name\\n- `\\"All\\"`: fire to every player\\n- `{ Except = PlayerName }`: fire to everyone except one player name\\n- `nil`: an implementation-defined default (see `Net`)","lua_type":"Player | PlayerName | { PlayerName } | \\"All\\" | { Except: PlayerName } | nil","source":{"line":73,"path":"src/init.luau"}},{"name":"ClientMeta","desc":"Metadata returned by the internal `__struktura_meta` request. This is used to build\\nclient-side service proxies in [Struktura.GetService].","fields":[{"name":"Signals","lua_type":"{string}","desc":"Signal names exposed on a service\'s `Client` table"},{"name":"Methods","lua_type":"{string}","desc":"Method names exposed on a service\'s `Client` table"}],"source":{"line":83,"path":"src/init.luau"}},{"name":"Connection","desc":"Minimal connection interface returned by Struktura signals.","fields":[{"name":"Disconnect","lua_type":"(self: Connection) -> ()","desc":"Disconnects the connection"}],"source":{"line":94,"path":"src/init.luau"}},{"name":"ClientSignal","desc":"A client-side signal wrapper. You typically obtain these from [Struktura.GetService].","fields":[{"name":"Connect","lua_type":"(self: ClientSignal<Args...>, callback: (Args...) -> ()) -> Connection","desc":""}],"source":{"line":104,"path":"src/init.luau"}},{"name":"ServerSignal","desc":"A server-side signal wrapper that routes through `Struktura.Net`.\\nYou create these indirectly by putting [Struktura.CreateSignal] markers in a service\'s `Client` table.","fields":[{"name":"Fire","lua_type":"(self: ServerSignal<Args...>, target: Target, Args...) -> ()","desc":""},{"name":"FireAll","lua_type":"(self: ServerSignal<Args...>, Args...) -> ()","desc":""},{"name":"FireList","lua_type":"(self: ServerSignal<Args...>, list: {PlayerName}, Args...) -> ()","desc":""},{"name":"FireExcept","lua_type":"(self: ServerSignal<Args...>, except: PlayerName, Args...) -> ()","desc":""}],"source":{"line":118,"path":"src/init.luau"}},{"name":"Settings","desc":"Configuration options for [Struktura.Configure].","fields":[{"name":"ServicePromises","lua_type":"boolean?","desc":"If true, client service method calls return a Promise-like object (default: true)"}],"source":{"line":131,"path":"src/init.luau"}}],"name":"Struktura","desc":"A lightweight services/controllers framework with a small networking surface.\\nStruktura is designed around two module \\"roles\\":\\n- **Services** (server): any module that does *not* set `Type == \\"Controller\\"`\\n- **Controllers** (client): modules that set `Type == \\"Controller\\"`\\nTypical boot flow:\\n```lua\\nlocal Struktura = require(ReplicatedStorage.Packages.Struktura)\\n-- Server\\nStruktura.Initialize(ServerScriptService.Services, true)\\nStruktura.Start():catch(warn)\\n-- Client\\nStruktura.Initialize(Players.LocalPlayer.PlayerScripts.Controllers, true)\\nStruktura.Start():catch(warn)\\n```\\n## Lifecycle\\nModules may optionally implement `Init` (runs before Start resolves) and `Start` (runs after).\\nStruktura also forwards a small set of lifecycle events to modules as `On<EventName>` methods:\\n- `OnPlayerAdded(player)`\\n- `OnPlayerRemoving(player)`\\n- `OnCharacterAdded(player, character)`\\n- `OnBindToClose(reason)` *(server only)*\\nYou can define your own lifecycle events with [Struktura.CreateLifecycle].\\n## Service client surface\\nServices can expose a `Client` table. Functions inside `Client` become RPC handlers callable from the client.\\nTo expose server \u2192 client signals, assign a field to the marker returned by [Struktura.CreateSignal]:\\n```lua\\nlocal Struktura = require(ReplicatedStorage.Packages.Struktura)\\nlocal MyService = { Name = \\"MyService\\" }\\nMyService.Client = {\\n    DataChanged = Struktura.CreateSignal(),\\n    GetData = function(self, player) return {} end,\\n}\\nreturn MyService\\n```\\nOn the client, use [Struktura.GetService] to access these methods and signals.","source":{"line":55,"path":"src/init.luau"}}')}}]);